function Plan({ mobile, t }: { mobile: boolean; t: Text }) {
  return <>{mobile && <header className="mobile-head"><span className="hamburger"/><span>{t('session')}</span><span className="tab">{t('conversation')}</span><span className="dots">⋮</span></header>}
    <div className={`plan${mobile ? ' phone-plan' : ''}`}><div className="question">{t('question')}</div><p className="answer">{t('answer')}</p><section className="tf-sum"><h3>{t('strategy')}</h3><dl className="rows">{(['asset','buy','sell','period'] as const).map((key, i) => <div className="r" key={key}><dt>{t(key)}</dt><dd>{t((['bitcoin','buyRule','sellRule','twoYears'] as const)[i])}</dd></div>)}</dl><p className="fee">{t('fee')}</p><button tabIndex={-1} className="pill">{t('replay')}</button></section></div>
    {mobile && <div className="composer">{t('composer')}<button tabIndex={-1} aria-hidden="true">↑</button></div>}</>
}

function Result({ mobile, t, value }: { mobile: boolean; t: Text; value: CatalogueBacktestObservation }) {
  const r = value.result, profit = value.amount * r.ret / 100, benchmarkProfit = value.amount * value.benchmarkReturn / 100
  const identity = catalogueIdentity(value.strategy), points = r.eq, W = mobile ? 358 : 776, H = mobile ? 240 : 340
  const left = mobile ? 46 : 64, right = W - 18, top = 26, bottom = H - 40
  const x = (i: number) => left + (i - points[0].i) / (points.at(-1)!.i - points[0].i) * (right - left)
  const y = (nav: number) => top + (1 - nav / 25000) * (bottom - top)
  const path = (series: readonly { i: number; v: number }[]) => series.map((p, i) => `${i ? 'L' : 'M'}${x(p.i).toFixed(3)},${y(p.v * value.amount).toFixed(3)}`).join(' ')
  const curve = path(points), benchmark = path(value.benchmark), wins = r.trades.filter(trade => trade.pnl > 0).length
  // Same stored equity, used only to locate the source's maximum-drawdown mark.
  let peak = points[0], drop = 0, dropFrom = peak.i, dropTo = peak.i
  for (const p of points) { if (p.v > peak.v) peak = p; const loss = p.v / peak.v - 1; if (loss < drop) { drop = loss; dropFrom = peak.i; dropTo = p.i } }
  return <div className={`report${mobile ? ' report-mobile' : ''}`}>
    <div className="report-heading">{mobile ? <span className="hamburger"/> : <><span>‹</span><b>{t('backtest')}</b><span>{t('fullBudget')}</span></>}</div>
    <div className="report-id"><ClientStrategyGlyph kind={identity.kind} evidence={identity.glyph} size={44}/><div><h1>{t('f1')}</h1><p>{t('f1Description')}</p><div className="tags"><span>{t('rule')}</span><span>BNB</span><span>{t('futures')}</span></div></div></div>
    <div className="report-grid"><div><div className="cap"><div className="balance"><small>{t('balance')}</small><strong className="num">{dollars(value.amount + profit)}</strong><i className="up num">{percent(r.ret)}</i></div><div className="legend"><span className="strategy">{t('thisStrategy')}</span><span className="initial">{t('initial')}</span><span className="hold">{t('hold')} {percent(value.benchmarkReturn)}</span><span>▲ {t('long')}</span><span>▼ {t('short')}</span><span>▽ {t('close')}</span></div></div>
      <svg className="plot" viewBox={`0 0 ${W} ${H}`} data-equity-count={points.length}><defs><linearGradient id="artwork-equity" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#2fb98a" stopOpacity=".13"/><stop offset="1" stopColor="#2fb98a" stopOpacity="0"/></linearGradient></defs>{[0,5000,10000,15000,20000,25000].map(n => <g key={n}><line x1={left} x2={right} y1={y(n)} y2={y(n)} stroke="#161616"/><text x={left - 10} y={y(n) + 4} textAnchor="end" fill="#999" fontSize="12">{n.toLocaleString('en-US')}</text></g>)}<path d={`${curve} L${right},${bottom} L${left},${bottom} Z`} fill="url(#artwork-equity)"/><path d={curve} fill="none" stroke="#2fb98a" strokeWidth="2" data-series="strategy"/><path d={benchmark} fill="none" stroke="#aaa" strokeWidth="1.4" strokeDasharray="2 3" data-series="benchmark"/><line x1={left} x2={right} y1={y(value.amount)} y2={y(value.amount)} stroke="#777" strokeWidth=".6"/>{r.events.filter(e => e.t === 'enter' || e.t === 'exit').map((event, j) => { const p = points.find(p => p.i === event.i); if (!p) return null; return <path key={j} d={event.t === 'exit' ? 'M0 4L5-4H-5Z' : event.side === -1 ? 'M0 4L5-4H-5Z' : 'M0-4L5 4H-5Z'} transform={`translate(${x(event.i)},${y(p.v * value.amount) + (event.t === 'exit' ? -7 : 7)})`} stroke="#ccc" strokeWidth={event.t === 'exit' ? 1.3 : 0} fill={event.t === 'exit' ? '#111' : '#aaa'}/> })}
        <g data-drawdown-from={dropFrom} data-drawdown-to={dropTo}><line x1={x(dropFrom)} x2={x(dropFrom)} y1={top} y2={bottom} stroke="#58383b" strokeDasharray="2 5"/><line x1={x(dropTo)} x2={x(dropTo)} y1={top} y2={bottom} stroke="#58383b" strokeDasharray="2 5"/><line x1={x(dropFrom)} x2={x(dropTo)} y1={bottom + 5} y2={bottom + 5} stroke="#999" strokeWidth="4" strokeLinecap="round"/><text x={right} y={bottom - 5} textAnchor="end" fill="#ccc" fontSize={mobile ? 10 : 12} fontWeight="600">{t('maxDrawdownInterval')} {r.mdd.toFixed(1)}%</text></g>
        {(mobile ? ['23.04','24.06','25.08','26.09'] : ['23.04','23.12','24.08','25.05','26.01','26.09']).map((date, i, all) => <text key={date} x={left + i / (all.length - 1) * (right - left)} y={H - 9} textAnchor={i === 0 ? 'start' : i === all.length - 1 ? 'end' : 'middle'} fill="#999" fontSize="12">{date}</text>)}
      </svg><p className="result-hint">● {t('resultHint',{days:points.length.toLocaleString('en-US')})}</p></div>
      <aside><section className="result-box"><small>{t('profitCaption')}</small><h2 className="profit up num">+{dollars(profit)}</h2><p>{t('holdProfit')} +{dollars(benchmarkProfit)}</p><p>{t('difference')} +{dollars(profit - benchmarkProfit)}</p><dl className="metrics"><div><dt>{t('maxDrawdown')}</dt><dd style={{color:'#e85b75'}}>{r.mdd.toFixed(1)}%</dd><small>{t('holdDrawdown')} {value.benchmarkMdd.toFixed(1)}%</small></div><div><dt>{t('winningTrades')}</dt><dd>{t('wins',{total:r.n,wins})}</dd></div><div><dt>{t('averageHold')}</dt><dd>{t('days',{days:Math.round(r.avgHold ?? 0)})}</dd></div></dl></section><section className="result-box interpretation"><h3>{t('interpretation')}</h3><p>{t('resultSummary',{difference:Math.round(profit-benchmarkProfit).toLocaleString('en-US'),drawdown:r.mdd.toFixed(1)})}</p></section></aside>
    </div>{mobile && <div className="mobile-cta"><div><b>{percent(r.ret)}</b>{t('all')}</div><button tabIndex={-1} className="pill">{t('execute')}</button></div>}
  </div>
}

function Exchange({ t }: { t: Text }) {
  return <section className="exchange"><h1><span>‹</span>{t('exchange')}</h1><p>{t('exchangeSub')}</p><div className="ex-grid">{planExchanges.map(([id, name]) => <button tabIndex={-1} key={id}><img src={`/client-broker-assets/app-${id}.${id === 'gate' ? 'jpg' : 'png'}`} alt=""/><span>{name}</span></button>)}</div><div className="support"><span>{t('support')}</span><span>{t('contact')}</span></div></section>
}

function Brain({ t, variant }: { t: Text; variant: 'compact' | 'mobile' | 'detail' }) {
  // The original mobile bitmap shows only the third event's header and opening
  // ADA sentence. No unseen trade metrics/body are reconstructed. Translations
  // are exact copies of client-catalogue-judgment-locale-copy.json's ADA key.
  return <section className={`brain ${variant}`}><p className="kind"><span>{t('basket')}</span><span>{t('aiCopied')}</span></p><h2>{t('holdingHeadline')}</h2><p className="schedule"><img src="/client-broker-assets/app-bitget.png" alt=""/>{t('schedule')}</p>
    <dl>{[['AVAX','17%','+3.2%'],['ADA','23%','+3.7%'],['SOL','27%','0.0%']].map(([asset,weight,profit])=><div key={asset}><dt>{asset} {t('holding')}</dt><dd><span>{t('weight')} {weight}</span><span className={profit.startsWith('+')?'up':''}>{profit}</span></dd></div>)}<div><dt>{t('cash')}</dt><dd><span>{t('weight')} 33%</span></dd></div><div className="exit"><dt>{t('exitRule')}</dt><dd>{t('exitValue')}</dd></div></dl>
    <section className="brain-section"><p className="label">{t('thought')}</p><p className="thought-body">{t('thoughtBody')} <span className="more">{t('more')}</span></p></section>
    <section className="brain-section"><h3>{t('history')}</h3>{[['09/27 08:00:40','spotBuy','solHistory'],['09/27 08:00:39','spotSell','bnbHistory']].map(([date,kind,body])=><article className="entry" key={date}><header><span>{date}</span><span>{t(kind as Key)}</span></header><p>{t(body as Key)} <span className="full">{t('fullDecision')}</span></p></article>)}{variant==='mobile'&&<article className="entry source-visible-prefix"><header><span>09/22 08:00:42</span><span>{t('spotBuy')}</span></header><p>{t('adaHistoryStart')}</p></article>}</section>
  </section>
}

function Terminal({ t }: { t: Text }) {
  return <div className="terminal"><header className="ticker"><div className="symbol"><span style={{position:'relative',overflow:'hidden',width:26,height:26,flexShrink:0}}><img src="/client-shots/about/about-live.webp" alt="" style={{position:'absolute',width:1376,height:900,maxWidth:'none',left:-29,top:-27}}/></span>AVAXUSDT <small>{t('perpetual')}</small><span>⌄</span></div><div className="price">10.913<small>-0.075 -0.68%</small></div>{([['markPrice','10.913'],['indexPrice','10.921'],['fundingTime','-0.0038% / 06:36:02'],['high','11.178'],['low','10.723'],['volumeAvax','15.47M'],['volumeUsd','169.73M']] as const).map(([key,value])=><div className="metric" key={key}><span>{t(key)}</span><b style={{fontWeight:400}}>{value}</b></div>)}</header>
    <div className="terminal-body"><section className="terminal-chart"><div className="chart-tabs"><span className="selected">{t('chart')}</span><span>{t('info')}</span><span>{t('data')}</span><span className="venue">◆ {t('binancePrice')}&#x3000; ▣ {t('bitgetRunning')}</span></div><div className="chart-toolbar"><span>{t('minute')}</span><span>{t('thirtyMinutes')}</span><span>{t('hour')}</span><span className="selected">{t('fifteenMinutes')}</span><span style={{position:'relative',overflow:'hidden',width:176,height:35,flexShrink:0}}><img src="/client-shots/about/about-live.webp" alt="" style={{position:'absolute',width:1376,height:900,maxWidth:'none',left:-195,top:-126}}/></span><span>{t('indicators')}</span></div>
      <div className="tool-crop"><img src="/client-shots/about/about-live.webp" alt=""/></div><div className="source-price-plot"><img src="/client-shots/about/about-live.webp" alt=""/><div className="plot-labels"><b>AVAX / TetherUS PERPETUAL CONTRACT · 15 · Binance</b><em>{t('openPrice')} 10.843&#x3000;{t('highPrice')} 10.935 {t('lowPrice')} 10.843 {t('closePrice')} 10.914 +0.071 (+0.65%)</em></div><div className="averages"><div>MA 7 close&#x3000;<span>10.872</span></div><div>MA 25 close&#x3000;<span>10.935</span></div><div>MA 99 close&#x3000;<span>10.979</span></div><div>{t('volume')} · AVAX&#x3000;<span>160.09K</span></div></div><span className="axis-month">{t('october')}</span></div>
    </section><Brain t={t} variant="compact"/></div>
    <section className="terminal-table"><nav>{(['currentStrategy','positions','openOrders','orders','fills','closedPositions','assets'] as const).map((key,i)=><span key={key} className={i===1?'active':''}>{t(key)}</span>)}</nav><p>{t('periodRecord')}</p><div className="table-head">{(['exchangeColumn','strategyColumn','symbol','direction','quantity','entryPrice','currentPrice','stopPrice','unrealized'] as const).map(key=><span key={key}>{t(key)}</span>)}<span>%</span></div><div className="data-strip"><img src="/client-shots/about/about-live.webp" alt=""/><span className="translated-title">{t('basket')}</span></div></section>
  </div>
}

export async function mount(shot: ArtworkShot, language: Language) {
  if (!Object.hasOwn(copy, language)) throw Error('Missing artwork translation')
  const words = Reflect.get(copy, language) as Record<Key, string>
  const t: Text = (key, values = {}) => { const text = words[key]; if (typeof text !== 'string' || !text.trim()) throw Error('Missing artwork copy: '+key); return text.replace(/\{(\w+)\}/g, (_, k) => { if (!Object.hasOwn(values,k)) throw Error('Missing artwork placeholder'); return String(values[k]) }) }
  const value = computeCatalogueBacktest({owner:'source-artwork-only',strategyId:'f1',period:0,amount:1000},await loadCatalogueMarketData())
  if (Math.abs(value.result.ret-2085.612206381291)>1e-8 || value.result.n!==13 || value.calendar.asof!=='2026-09-28') throw Error('Source artwork numeric oracle changed')
  document.documentElement.lang = language
  const root = createRoot(document.getElementById('fixture')!)
  flushSync(() => root.render(<><style>{styling + captureRefinements + mobileViewportRefinements}</style><main className="artwork" data-shot={shot} data-language={language} data-source-artwork="9fbff821" aria-label="Source artwork illustration">{shot === 'about-live' ? <Terminal t={t}/> : shot === 'about-brain' || shot === 'dl-live' ? <Brain t={t} variant={shot==='dl-live'?'mobile':'detail'}/> : shot === 'about-connect' ? <Exchange t={t}/> : shot === 'dl-chat' || shot === 'about-plan2' ? <Plan mobile={shot === 'dl-chat'} t={t}/> : <Result mobile={shot === 'dl-report'} t={t} value={value}/>}</main></>))
  return { shot, language, source:'source-artwork-illustration-only', sourceSha:'9fbff821df62cad11d026022fc7628c7fcebc431', calculationSha:value.sourceSha,
    metrics:{return:value.result.ret,trades:value.result.n,mdd:value.result.mdd,benchmark:value.benchmarkReturn,benchmarkMdd:value.benchmarkMdd,averageHold:value.result.avgHold,wins:value.result.trades.filter(t=>t.pnl>0).length},
    equity:value.result.eq,benchmark:value.benchmark,serviceApi:false,accountState:false,executionAuthority:false,
  }
}
